package com.lovemaptually.repository;import com.lovemaptually.entity.Place;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface PlaceRepository extends JpaRepository<Place,Long>{Optional<Place> findByProviderAndProviderPlaceId(String provider,String providerPlaceId);@Query("select p from Place p where (lower(p.name) like lower(concat('%',:q,'%')) or lower(p.address) like lower(concat('%',:q,'%')) or lower(p.category) like lower(concat('%',:q,'%'))) and (:r is null or p.region=:r)") Page<Place> search(@Param("q")String query,@Param("r")String region,Pageable pageable);@Query("select distinct p.region from Place p order by length(p.region) desc")List<String> findRegions();}
